/** Decimal HALF_UP: 2.5 -> 3, 2.45 -> 2.5 at scale 1, etc. */
private static function halfUp(string $n, int $places): string
{
    if ($places < 0) {
        throw new \InvalidArgumentException('Places must be >= 0');
    }
    // bcadd with a 0.5-ulp at the right place implements HALF_UP for
    // non-negative numbers and ties-away-from-zero is equivalent here.
    $half = '0.' . str_pad('5', $places + 1, '0'); // 0.0000005 at places=6
    // actually half ulp at $places is 0.<$places zeros><5 at places+1>
    $half = '0.' . str_repeat('0', $places) . '5';
    // truncate to $places after adding half
    $summed = bcadd($n, $half, $places + 1);
    // drop the last digit
    $summed = preg_replace('/(\.[0-9]{'.$places.'})[0-9]?.*$/s', '$1', $summed);
    if (str_starts_with($n, '-') && self::isZero($summed)) {
        return self::pad('0', $places);
    }
    return self::pad($summed, $places);
}

