<?php

declare(strict_types=1);

namespace App\Infrastructure;

use Doctrine\ORM\EntityManagerInterface;
use Doctrine\Persistence\ObjectRepository;

/**
 * Instantiate our sub-class of Doctrine's EntityRepository with the entity
 * FQCN and the EntityManager. Avoids the factory round-trip through
 * Doctrine's DefaultRepositoryFactory (which can re-resolve the class and
 * re-trigger the autoloader mid-container).
 *
 * @template T of ObjectRepository
 * @param class-string<T> $repositoryClass
 * @param class-string    $entityClass
 * @return T
 */
function makeRepository(EntityManagerInterface $em, string $repositoryClass, string $entityClass): ObjectRepository
{
    $metadata = $em->getClassMetadata($entityClass);
    $repo = new $repositoryClass($em, $metadata);
    return $repo;
}
